#!/usr/bin/env python3
"""Load all samples into FT2"""
import json, subprocess

with open('/workspace/samples_info.json') as f:
    samples = json.load(f)

batch = []

for name, info in samples.items():
    # Create sample from PCM
    batch.append({
        "name": "sample_create_from_pcm",
        "arguments": {
            "instrument": info['inst'],
            "sample": 0,
            "pcm": info['data'],
            "encoding": "int16",
            "name": info['name']
        }
    })

    # Set sample metadata (loop, volume, etc.)
    flags = 0
    if info['loop_length'] > 0:
        flags = 1  # forward loop

    sample_args = {
        "instrument": info['inst'],
        "sample": 0,
        "volume": 64,
        "panning": 128,
        "flags": flags
    }
    if info['loop_length'] > 0:
        sample_args['loop_start'] = info['loop_start']
        sample_args['loop_length'] = info['loop_length']
    if info.get('relative_note', 0) != 0:
        sample_args['relative_note'] = info['relative_note']

    batch.append({
        "name": "sample_set",
        "arguments": sample_args
    })

    # Set instrument name
    batch.append({
        "name": "instrument_set",
        "arguments": {
            "instrument": info['inst'],
            "name": info['name']
        }
    })

with open('/workspace/load_samples_batch.json', 'w') as f:
    json.dump(batch, f)

print(f"Generated batch with {len(batch)} commands")
